#!/usr/bin/env bash
# The committed native/Agenthail.xcodeproj is generated by exactly this XcodeGen release.
set -euo pipefail

VERSION=2.44.1
SHA256=a2e905fb68446e9bb4008cdfe2e13e3f176d0cbcca828b71770f8e53fca91b73

repo="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cache="${RUNNER_TEMP:-${TMPDIR:-/tmp}}/agenthail-xcodegen"
archive="$cache/xcodegen-$VERSION.zip"
"$repo/scripts/verified-download.sh" "https://github.com/yonaskolb/XcodeGen/releases/download/$VERSION/xcodegen.zip" "$archive" "$SHA256"
unpacked="$(mktemp -d "$cache/unpack.XXXXXX")"
trap 'rm -rf "$unpacked"' EXIT
unzip -q "$archive" -d "$unpacked"
"$unpacked/xcodegen/bin/xcodegen" "$@"
